60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
69	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
70	     * addresses are lower-cased before being stored.
71	     */
72	    private static final Pattern EMAIL_PATTERN =
73	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
74	
75	    /**
76	     * Maximum number of owners a single city may contain. A create that would take the owner's city
77	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
78	     */
79	    private static final int CITY_OWNER_LIMIT = 50;
80	
81	    /**
82	     * Maximum number of owners that may be registered on a single day. A create that would take the
83	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
84	     * have already been created that day - is rejected with a 429.
85	     */
86	    private static final int DAILY_OWNER_LIMIT = 100;
87	
88	    private final ClinicService clinicService;
89	
90	    private final OwnerMapper ownerMapper;
91	
92	    private final PetMapper petMapper;
93	
94	    private final VisitMapper visitMapper;
95	
96	    public OwnerRestControllerV1(ClinicService clinicService,
97	                                 OwnerMapper ownerMapper,
98	                                 PetMapper petMapper,
99	                                 VisitMapper visitMapper) {
100	        this.clinicService = clinicService;
101	        this.ownerMapper = ownerMapper;
102	        this.petMapper = petMapper;
103	        this.visitMapper = visitMapper;
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
109	        Collection<Owner> owners;
110	        if (lastName != null) {
111	            owners = this.clinicService.findOwnerByLastName(lastName);
112	        } else {
113	            owners = this.clinicService.findAllOwners();
114	        }
115	        if (owners.isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
124	        Owner owner = this.clinicService.findOwnerById(ownerId);
125	        if (owner == null) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
134	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
135	        validateRequiredFields(ownerFieldsDto);
136	        HttpHeaders headers = new HttpHeaders();
137	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
138	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
139	        owner.setEmail(normalizeEmail(owner.getEmail()));
140	        if (owner.getRegistrationDate() == null) {
141	            owner.setRegistrationDate(LocalDate.now());
142	        }
143	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
144	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
145	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
146	        }
147	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
148	            && isDuplicateHousehold(owner.getLastName(), owner.getAddress())) {
149	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
150	        }
151	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
152	            throw new OwnerCityFullException(owner.getCity());
153	        }
154	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= DAILY_OWNER_LIMIT) {
155	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
156	        }
157	        owner.setCustomerCode(buildCustomerCode(owner.getCity(), owner.getLastName()));
158	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getAddress()));
159	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
160	        this.clinicService.saveOwner(owner);
161	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
162	        headers.setLocation(UriComponentsBuilder.newInstance()
163	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
164	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
165	    }
166	
167	    /**
168	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
169	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
170	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
171	     * checked in its {@link AddressNormalizer#normalize normalized} form, so a value that is blank only
172	     * after normalization is still rejected.
173	     *
174	     * @param ownerFieldsDto the submitted owner fields
175	     */
176	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
177	        List<String> missingFields = new ArrayList<>();
178	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
179	            missingFields.add("firstName");
180	        }
181	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
182	            missingFields.add("lastName");
183	        }
184	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
185	            missingFields.add("address");
186	        }
187	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
188	            missingFields.add("city");
189	        }
190	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
191	            missingFields.add("telephone");
192	        }
193	        if (!missingFields.isEmpty()) {
194	            throw new MissingOwnerFieldsException(missingFields);
195	        }
196	    }
197	
198	    /**
199	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
200	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
201	     * address; the accepted value is lower-cased before it is stored and returned.
202	     *
203	     * @param email the raw email value submitted by the client, or {@code null}
204	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
205	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
206	     */
207	    private String normalizeEmail(String email) {
208	        if (!StringUtils.hasText(email)) {
209	            return email;
210	        }
211	        if (!EMAIL_PATTERN.matcher(email).matches()) {
212	            throw new InvalidOwnerFieldsException(List.of("email"));
213	        }
214	        return email.toLowerCase();
215	    }
216	
217	    /**
218	     * Builds the owner's customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where CITY3 is the
219	     * upper-cased first three letters of the city, LAST3 is the upper-cased first three letters of the
220	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
221	     * of owners already in that city (e.g. {@code SYD-SMI-0007}).
222	     *
223	     * @param city the owner's city
224	     * @param lastName the owner's last name
225	     * @return the assigned customer code
226	     */
227	    private String buildCustomerCode(String city, String lastName) {
228	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
229	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
230	        int sequence = (int) this.clinicService.findAllOwners().stream()
231	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
232	            .count() + 1;
233	        return String.format("%s-%s-%04d", city3, last3, sequence);
234	    }
235	
236	    /**
237	     * Determines whether an existing owner already shares a household with the supplied last name and
238	     * address. Two owners belong to the same household when {@link HouseholdNormalizer#sameHousehold}
239	     * considers their last name and address a match.
240	     *
241	     * @param lastName the submitted owner's last name
242	     * @param address the submitted owner's address
243	     * @return {@code true} if another owner already has the same normalized last name and address
244	     */
245	    /**
246	     * Counts how many owners already exist that share the supplied first and last name, compared
247	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
248	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
249	     *
250	     * @param firstName the submitted owner's first name
251	     * @param lastName the submitted owner's last name
252	     * @return the number of existing owners with the same first and last name, ignoring case
253	     */
254	    private int countNamesakes(String firstName, String lastName) {
255	        return (int) this.clinicService.findAllOwners().stream()
256	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
257	                && lastName.equalsIgnoreCase(existing.getLastName()))
258	            .count();
259	    }
260	
261	    private boolean isDuplicateHousehold(String lastName, String address) {
262	        return this.clinicService.findAllOwners().stream()
263	            .anyMatch(existing -> HouseholdNormalizer.sameHousehold(
264	                lastName, address, existing.getLastName(), existing.getAddress()));
265	    }
266	
267	    /**
268	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
269	     * enforce the per-city capacity limit when a new owner is created.
270	     *
271	     * @param city the submitted owner's city
272	     * @return the number of existing owners in that city, ignoring case
273	     */
274	    private long countOwnersInCity(String city) {
275	        return this.clinicService.findAllOwners().stream()
276	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
277	            .count();
278	    }
279	
280	    /**
281	     * Counts how many owners have already been created on the supplied registration date. Used to
282	     * enforce the per-day capacity limit when a new owner is created.
283	     *
284	     * @param registrationDate the registration date of the owner being created
285	     * @return the number of existing owners already registered on that date
286	     */
287	    /**
288	     * Rolls a registration date forward to a business day. A registration date must fall on a
289	     * business day, so when the supplied or defaulted date lands on a Saturday or Sunday it is
290	     * moved forward to the following Monday; a weekday is returned unchanged. Every value derived
291	     * from the registration date (such as the membership number's year segment) and the daily
292	     * create-limit therefore use the adjusted date.
293	     *
294	     * @param date the effective registration date, whether supplied or defaulted to the server date
295	     * @return the same date when it is a weekday, otherwise the next Monday
296	     */
297	    private LocalDate toBusinessDay(LocalDate date) {
298	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
299	            date = date.plusDays(1);
300	        }
301	        return date;
302	    }
303	
304	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
305	        return this.clinicService.findAllOwners().stream()
306	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
307	            .count();
308	    }
309	
310	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
311	    @Override
312	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
313	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
314	        if (currentOwner == null) {
315	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
316	        }
317	        currentOwner.setAddress(ownerFieldsDto.getAddress());
318	        currentOwner.setCity(ownerFieldsDto.getCity());
319	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
320	        currentOwner.setLastName(ownerFieldsDto.getLastName());
321	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
322	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
323	        this.clinicService.saveOwner(currentOwner);
324	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
325	    }
326	
327	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
328	    @Transactional
329	    @Override
330	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
331	        Owner owner = this.clinicService.findOwnerById(ownerId);
332	        if (owner == null) {
333	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
334	        }
335	        this.clinicService.deleteOwner(owner);
336	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
337	    }
338	
339	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
340	    @Override
341	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
342	        Owner owner = this.clinicService.findOwnerById(ownerId);
343	        if (owner == null) {
344	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
345	        }
346	        HttpHeaders headers = new HttpHeaders();
347	        Pet pet = petMapper.toPet(petFieldsDto);
348	        owner.setId(ownerId);
349	        pet.setOwner(owner);
350	        pet.getType().setName(null);
351	        this.clinicService.savePet(pet);
352	        PetDto petDto = petMapper.toPetDto(pet);
353	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
354	            .buildAndExpand(pet.getId()).toUri());
355	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
356	    }
357	
358	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
359	    @Override
360	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
361	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
362	        if (currentOwner != null) {
363	            Pet currentPet = this.clinicService.findPetById(petId);
364	            if (currentPet != null) {
365	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
366	                currentPet.setName(petFieldsDto.getName());
367	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
368	                this.clinicService.savePet(currentPet);
369	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
370	            }
371	        }
372	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
373	    }
374	
375	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
376	    @Override
377	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
378	        HttpHeaders headers = new HttpHeaders();
379	        Visit visit = visitMapper.toVisit(visitFieldsDto);
380	        Pet pet = new Pet();
381	        pet.setId(petId);
382	        visit.setPet(pet);
383	        this.clinicService.saveVisit(visit);
384	        VisitDto visitDto = visitMapper.toVisitDto(visit);
385	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
386	            .buildAndExpand(visit.getId()).toUri());
387	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
388	    }
389	
390	
391	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
392	    @Override
393	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
394	        Owner owner = this.clinicService.findOwnerById(ownerId);
395	        if (owner != null) {
396	            Pet pet = owner.getPet(petId);
397	            if (pet != null) {
398	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
399	            }
400	        }
401	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
402	    }
403	}
