3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's locality (region) from their city using a fixed
7	 * city-to-region table. Kept as a plain static helper - rather than a method on
8	 * {@link OwnerMapper} - so MapStruct does not mistake it for an implicit
9	 * String-to-String property mapping and apply it to unrelated fields.
10	 */
11	final class OwnerLocality {
12	
13	    /** City -> canonical region; anything not listed derives locality "UNKNOWN". */
14	    private static final Map<String, String> CITY_REGION = Map.of(
15	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
16	
17	    private OwnerLocality() {
18	    }
19	
20	    /**
21	     * Returns the canonical region for the given city, or "UNKNOWN" when the city
22	     * is not in the fixed table (or is {@code null}).
23	     *
24	     * @param city the owner's city
25	     * @return the derived locality (region)
26	     */
27	    static String forCity(String city) {
28	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
29	    }
30	
31	}
